objects.script:
// Box runner — flee, HP, double-safe respawn

if (!window.__runners) window.__runners = [];

if (object && !object.userData._runnerBound) {
  object.userData._runnerBound = true;

  const spawnPos = object.position.clone();
  const spawnRotY = object.rotation.y;

  const state = {
    object: object,
    alive: true,
    health: 100,
    maxHealth: 100,
    fleeRange: 6,
    speed: 3.2,
    reactDelay: 0.35,
    fearTimer: 0,
    respawnAt: 0,
    spawnPos: spawnPos,
    spawnRotY: spawnRotY,
    bar: null,
    takeDamage: function (amt) {
      if (!state.alive) return;
      state.health = Math.max(0, state.health - amt);
      state.fearTimer = -0.4;
      syncBar();
      log('Box HP: ' + state.health);
      if (state.health <= 0) {
        state.alive = false;
        object.visible = false;
        if (state.bar) state.bar.style.display = 'none';
        // Respawn in 3s — schedule twice so it can't get lost
        state.respawnAt = performance.now() + 3000;
        setTimeout(function () { tryRespawn(state); }, 3000);
        setTimeout(function () { tryRespawn(state); }, 3200);
        log('Box down — respawn 3s');
      }
    }
  };

  function syncBar() {
    if (!state.bar) return;
    const pct = state.health / state.maxHealth;
    const fill = state.bar.querySelector('.hp-fill');
    fill.style.width = (pct * 100) + '%';
    fill.style.background = pct > 0.5 ? '#4caf7d' : pct > 0.25 ? '#e8a33d' : '#e0615a';
  }

  function tryRespawn(s) {
    if (s.alive) return;
    s.alive = true;
    s.health = s.maxHealth;
    s.fearTimer = 0;
    s.object.visible = true;
    s.object.position.copy(s.spawnPos);
    s.object.rotation.y = s.spawnRotY;
    s.respawnAt = 0;
    syncBar();
    if (s.bar) s.bar.style.display = 'block';
    log('Box respawned');
  }
  state.tryRespawn = tryRespawn;

  const wrap = document.getElementById('viewport-wrap');
  if (wrap) {
    const bar = document.createElement('div');
    bar.style.cssText = 'position:absolute;width:70px;height:9px;background:rgba(0,0,0,.55);border-radius:4px;overflow:hidden;z-index:30;pointer-events:none;border:1px solid rgba(255,255,255,.25)';
    const fill = document.createElement('div');
    fill.className = 'hp-fill';
    fill.style.cssText = 'height:100%;width:100%;background:#4caf7d';
    bar.appendChild(fill);
    wrap.appendChild(bar);
    state.bar = bar;
  }

  window.__runners.push(state);

  if (typeof onStop === 'function') {
    onStop(function () {
      window.__runners = (window.__runners || []).filter(function (r) { return r !== state; });
      if (state.bar) state.bar.remove();
      object.userData._runnerBound = false;
    });
  }
  log('Box runner + respawn ready');
}

function update(delta) {
  if (!object) return;
  delta = Math.min(delta || 0.016, 0.05);

  let state = null;
  for (let i = 0; i < (window.__runners || []).length; i++) {
    if (window.__runners[i].object === object) { state = window.__runners[i]; break; }
  }
  if (!state) return;

  // Backup respawn check every frame
  if (!state.alive && state.respawnAt && performance.now() >= state.respawnAt) {
    state.tryRespawn(state);
  }
  if (!state.alive || !object.visible) return;

  const huggy = window.__huggyObject;
  if (!huggy) return;

  const dist = object.position.distanceTo(huggy.position);
  if (dist < state.fleeRange) state.fearTimer += delta;
  else state.fearTimer = Math.max(0, state.fearTimer - delta);

  if (state.fearTimer > state.reactDelay) {
    const dx = object.position.x - huggy.position.x;
    const dz = object.position.z - huggy.position.z;
    const len = Math.sqrt(dx * dx + dz * dz) || 1;
    object.position.x += (dx / len) * state.speed * delta;
    object.position.z += (dz / len) * state.speed * delta;
    object.rotation.y = Math.atan2(dx, dz);
  }

  if (state.bar) {
    const pos = new THREE.Vector3(object.position.x, object.position.y + 1.3, object.position.z);
    pos.project(camera);
    if (pos.z < 1) {
      const wrap = document.getElementById('viewport-wrap');
      const w = wrap.clientWidth, h = wrap.clientHeight;
      state.bar.style.display = 'block';
      state.bar.style.left = ((pos.x * 0.5 + 0.5) * w - 35) + 'px';
      state.bar.style.top = ((-pos.y * 0.5 + 0.5) * h - 14) + 'px';
    } else state.bar.style.display = 'none';
  }
}

// Huggy — start menu + mobile GUI + safe attack/jump anims

if (!window.__huggy) {
  window.__huggy = {
    w: false, a: false, s: false, d: false, shift: false,
    yaw: 0, pitch: 0.35,
    dist: 10, distMin: 4, distMax: 16,
    walkSpeed: 5.5, sprintSpeed: 9.5,
    sens: 0.0035, minPitch: -0.25, maxPitch: 1.55,
    locked: false, started: false, isMobile: false,
    mixer: null, actions: {},
    lockUntil: 0, lockName: '',
    attackIndex: 0,
    stamina: 100, maxStamina: 100, staminaDrain: 28, staminaRegen: 18,
    attackRange: 5, attackDamage: 25,
    inputX: 0, inputZ: 0,
    vy: 0, groundedY: 0, onGround: true, jumpForce: 7, gravity: 22,
    stickActive: false, stickX: 0, stickY: 0
  };

  const k = window.__huggy;
  if (object) {
    window.__huggyObject = object;
    k.yaw = object.rotation.y;
    k.groundedY = object.position.y;
  }

  function onKeyDown(e) {
    if (!k.started) return;
    if (e.code === 'KeyW' || e.code === 'ArrowUp') k.w = true;
    if (e.code === 'KeyS' || e.code === 'ArrowDown') k.s = true;
    if (e.code === 'KeyA' || e.code === 'ArrowLeft') k.a = true;
    if (e.code === 'KeyD' || e.code === 'ArrowRight') k.d = true;
    if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') k.shift = true;
    if (e.code === 'KeyE') { e.preventDefault(); if (!e.repeat) tryAttack(); }
    if (e.code === 'Space') { e.preventDefault(); tryJump(); }
    if (e.code === 'Equal' || e.code === 'NumpadAdd') k.dist = Math.max(k.distMin, k.dist - 0.8);
    if (e.code === 'Minus' || e.code === 'NumpadSubtract') k.dist = Math.min(k.distMax, k.dist + 0.8);
  }
  function onKeyUp(e) {
    if (e.code === 'KeyW' || e.code === 'ArrowUp') k.w = false;
    if (e.code === 'KeyS' || e.code === 'ArrowDown') k.s = false;
    if (e.code === 'KeyA' || e.code === 'ArrowLeft') k.a = false;
    if (e.code === 'KeyD' || e.code === 'ArrowRight') k.d = false;
    if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') k.shift = false;
  }
  function onMouse(e) {
    if (!k.started || !k.locked || k.isMobile) return;
    k.yaw -= (e.movementX || 0) * k.sens;
    k.pitch += (e.movementY || 0) * k.sens;
    k.pitch = Math.max(k.minPitch, Math.min(k.maxPitch, k.pitch));
  }
  function onWheel(e) {
    if (!k.started) return;
    k.dist = Math.max(k.distMin, Math.min(k.distMax, k.dist + (e.deltaY > 0 ? 0.6 : -0.6)));
  }
  function onClick() {
    if (!k.started || k.isMobile) return;
    const c = document.querySelector('canvas');
    if (c) c.requestPointerLock();
  }
  function onLock() {
    k.locked = document.pointerLockElement === document.querySelector('canvas');
  }

  window.addEventListener('keydown', onKeyDown, true);
  window.addEventListener('keyup', onKeyUp, true);
  window.addEventListener('mousemove', onMouse, true);
  window.addEventListener('wheel', onWheel, { passive: true });
  window.addEventListener('click', onClick, true);
  document.addEventListener('pointerlockchange', onLock);

  buildStartScreen();

  k._cleanup = function () {
    window.removeEventListener('keydown', onKeyDown, true);
    window.removeEventListener('keyup', onKeyUp, true);
    window.removeEventListener('mousemove', onMouse, true);
    window.removeEventListener('click', onClick, true);
    document.removeEventListener('pointerlockchange', onLock);
    if (k.mixer) k.mixer.stopAllAction();
    ['start-screen', 'stamina-hud', 'mobile-ui', 'zoom-ui'].forEach(function (id) {
      const el = document.getElementById(id);
      if (el) el.remove();
    });
    if (document.pointerLockElement) document.exitPointerLock();
    window.__huggy = null;
    window.__huggyObject = null;
  };
  if (typeof onStop === 'function') onStop(k._cleanup);
  log('Huggy loaded — pick Mobile or Desktop');
}

function isLocked() {
  return performance.now() < (window.__huggy.lockUntil || 0);
}

function buildStartScreen() {
  const wrap = document.getElementById('viewport-wrap');
  if (!wrap || document.getElementById('start-screen')) return;

  const screen = document.createElement('div');
  screen.id = 'start-screen';
  screen.innerHTML = [
    '<div style="position:absolute;inset:0;z-index:100;display:flex;flex-direction:column;align-items:center;justify-content:center;',
    'background:radial-gradient(ellipse at center,rgba(20,8,12,.92) 0%,rgba(5,2,6,.97) 70%);',
    'backdrop-filter:blur(6px);font-family:Manrope,system-ui,sans-serif;color:#e8d5d5;">',
    '<div style="font-size:11px;letter-spacing:.35em;text-transform:uppercase;color:#8a6060;margin-bottom:10px;">CloudFurm</div>',
    '<div style="font-size:clamp(28px,6vw,42px);font-weight:800;letter-spacing:.06em;text-shadow:0 0 40px rgba(180,40,40,.45);margin-bottom:8px;">H U G G Y</div>',
    '<div style="font-size:13px;color:#9a7070;margin-bottom:36px;opacity:.85;">choose your experience</div>',
    '<div style="display:flex;gap:14px;flex-wrap:wrap;justify-content:center;padding:0 16px;">',
    '<button id="btn-start-mobile" type="button" style="',
    'min-width:150px;padding:16px 28px;border-radius:12px;cursor:pointer;',
    'background:rgba(120,20,30,.25);border:1px solid rgba(200,60,70,.45);',
    'color:#f0c0c0;font:700 14px Manrope,system-ui;letter-spacing:.12em;text-transform:uppercase;',
    'box-shadow:0 0 24px rgba(160,30,40,.2), inset 0 1px 0 rgba(255,180,180,.12);',
    'backdrop-filter:blur(8px);">Mobile</button>',
    '<button id="btn-start-desktop" type="button" style="',
    'min-width:150px;padding:16px 28px;border-radius:12px;cursor:pointer;',
    'background:rgba(40,20,50,.3);border:1px solid rgba(140,100,160,.4);',
    'color:#d8c8e8;font:700 14px Manrope,system-ui;letter-spacing:.12em;text-transform:uppercase;',
    'box-shadow:0 0 24px rgba(80,40,100,.2), inset 0 1px 0 rgba(220,200,255,.1);',
    'backdrop-filter:blur(8px);">Desktop</button>',
    '</div>',
    '<div style="margin-top:28px;font-size:11px;color:#6a5050;text-align:center;line-height:1.6;">',
    'WASD · Shift sprint · E attack · Space jump · Scroll zoom<br>Mobile: stick · ATK · SPR · JMP · look on right',
    '</div></div>'
  ].join('');
  wrap.appendChild(screen);

  document.getElementById('btn-start-mobile').onclick = function () { startGame(true); };
  document.getElementById('btn-start-desktop').onclick = function () { startGame(false); };
}

function startGame(mobile) {
  const k = window.__huggy;
  k.started = true;
  k.isMobile = mobile;
  const ss = document.getElementById('start-screen');
  if (ss) ss.remove();
  buildGameHUD(mobile);
  if (!mobile) {
    const c = document.querySelector('canvas');
    if (c) try { c.requestPointerLock(); } catch (err) {}
  }
  if (mobile) {
    document.documentElement.style.touchAction = 'none';
    const canvas = document.querySelector('canvas');
    if (canvas) canvas.style.touchAction = 'none';
  }
  log(mobile ? 'Mobile mode' : 'Desktop mode');
}

function btnHtml(id, label, title) {
  return '<button id="' + id + '" title="' + title + '" type="button" style="' +
    'pointer-events:auto;width:44px;height:44px;border-radius:10px;cursor:pointer;' +
    'background:rgba(30,10,14,.45);border:1px solid rgba(180,70,70,.4);' +
    'color:#e8c8c8;font:700 16px Manrope,system-ui;' +
    'backdrop-filter:blur(10px);box-shadow:0 4px 20px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,200,200,.1);' +
    '">' + label + '</button>';
}

function buildGameHUD(mobile) {
  const wrap = document.getElementById('viewport-wrap');
  if (!wrap) return;

  if (!document.getElementById('stamina-hud')) {
    const hud = document.createElement('div');
    hud.id = 'stamina-hud';
    hud.style.cssText = 'position:absolute;bottom:' + (mobile ? '130px' : '24px') +
      ';left:50%;transform:translateX(-50%);width:min(220px,50vw);height:8px;background:rgba(0,0,0,.4);border-radius:6px;overflow:hidden;z-index:40;border:1px solid rgba(180,80,80,.25)';
    const fill = document.createElement('div');
    fill.id = 'stamina-fill';
    fill.style.cssText = 'height:100%;width:100%;background:linear-gradient(90deg,#6a2030,#c04050)';
    hud.appendChild(fill);
    wrap.appendChild(hud);
  }

  if (!document.getElementById('zoom-ui')) {
    const z = document.createElement('div');
    z.id = 'zoom-ui';
    z.style.cssText = 'position:absolute;top:14px;right:14px;display:flex;flex-direction:column;gap:8px;z-index:40;';
    z.innerHTML = btnHtml('zoom-in', '+', 'Zoom in') + btnHtml('zoom-out', '−', 'Zoom out');
    wrap.appendChild(z);
    document.getElementById('zoom-in').onclick = function (e) { e.stopPropagation(); window.__huggy.dist = Math.max(window.__huggy.distMin, window.__huggy.dist - 1); };
    document.getElementById('zoom-out').onclick = function (e) { e.stopPropagation(); window.__huggy.dist = Math.min(window.__huggy.distMax, window.__huggy.dist + 1); };
  }

  if (!mobile || document.getElementById('mobile-ui')) return;

  const ui = document.createElement('div');
  ui.id = 'mobile-ui';
  ui.style.cssText = 'position:absolute;inset:0;z-index:35;pointer-events:none;';
  ui.innerHTML = [
    '<div id="stick-base" style="pointer-events:auto;position:absolute;left:20px;bottom:24px;width:120px;height:120px;border-radius:50%;',
    'background:rgba(20,8,12,.35);border:1px solid rgba(180,70,70,.35);backdrop-filter:blur(10px);',
    'box-shadow:0 0 30px rgba(100,20,30,.25), inset 0 0 20px rgba(0,0,0,.3);">',
    '<div id="stick-knob" style="position:absolute;left:35px;top:35px;width:50px;height:50px;border-radius:50%;',
    'background:radial-gradient(circle at 35% 30%,rgba(220,140,140,.55),rgba(80,20,30,.7));',
    'border:1px solid rgba(255,180,180,.25);box-shadow:0 4px 16px rgba(0,0,0,.4);"></div></div>',
    '<div style="pointer-events:auto;position:absolute;right:18px;bottom:28px;display:flex;flex-direction:column;gap:12px;align-items:center;">',
    btnHtml('btn-atk', 'ATK', 'Attack'),
    btnHtml('btn-spr', 'SPR', 'Sprint'),
    btnHtml('btn-jmp', 'JMP', 'Jump'),
    '</div>'
  ].join('');
  wrap.appendChild(ui);

  ['btn-atk', 'btn-spr', 'btn-jmp'].forEach(function (id) {
    const b = document.getElementById(id);
    if (!b) return;
    b.style.width = '64px';
    b.style.height = '64px';
    b.style.borderRadius = '50%';
    b.style.fontSize = '11px';
  });
  const atkBtn = document.getElementById('btn-atk');
  if (atkBtn) atkBtn.style.background = 'rgba(140,25,35,.4)';

  const base = document.getElementById('stick-base');
  const knob = document.getElementById('stick-knob');
  const k = window.__huggy;
  const maxR = 36;

  function setStick(cx, cy) {
    const rect = base.getBoundingClientRect();
    const ox = rect.left + rect.width / 2;
    const oy = rect.top + rect.height / 2;
    let dx = cx - ox, dy = cy - oy;
    const len = Math.sqrt(dx * dx + dy * dy) || 1;
    if (len > maxR) { dx = dx / len * maxR; dy = dy / len * maxR; }
    knob.style.left = (35 + dx) + 'px';
    knob.style.top = (35 + dy) + 'px';
    k.stickX = dx / maxR;
    k.stickY = dy / maxR;
    k.stickActive = true;
  }
  function endStick() {
    knob.style.left = '35px';
    knob.style.top = '35px';
    k.stickX = 0; k.stickY = 0; k.stickActive = false;
  }

  base.addEventListener('touchstart', function (e) { e.preventDefault(); setStick(e.touches[0].clientX, e.touches[0].clientY); }, { passive: false });
  base.addEventListener('touchmove', function (e) { e.preventDefault(); setStick(e.touches[0].clientX, e.touches[0].clientY); }, { passive: false });
  base.addEventListener('touchend', function (e) { e.preventDefault(); endStick(); });

  let lookTouch = null;
  wrap.addEventListener('touchstart', function (e) {
    if (!k.started || !k.isMobile) return;
    for (let i = 0; i < e.changedTouches.length; i++) {
      const t = e.changedTouches[i];
      if (t.clientX > window.innerWidth * 0.45) lookTouch = { id: t.identifier, x: t.clientX, y: t.clientY };
    }
  }, { passive: true });
  wrap.addEventListener('touchmove', function (e) {
    if (!lookTouch) return;
    for (let i = 0; i < e.changedTouches.length; i++) {
      const t = e.changedTouches[i];
      if (t.identifier !== lookTouch.id) continue;
      k.yaw -= (t.clientX - lookTouch.x) * 0.005;
      k.pitch += (t.clientY - lookTouch.y) * 0.005;
      k.pitch = Math.max(k.minPitch, Math.min(k.maxPitch, k.pitch));
      lookTouch.x = t.clientX; lookTouch.y = t.clientY;
    }
  }, { passive: true });
  wrap.addEventListener('touchend', function (e) {
    for (let i = 0; i < e.changedTouches.length; i++) {
      if (lookTouch && e.changedTouches[i].identifier === lookTouch.id) lookTouch = null;
    }
  });

  document.getElementById('btn-atk').addEventListener('touchstart', function (e) { e.preventDefault(); tryAttack(); }, { passive: false });
  document.getElementById('btn-jmp').addEventListener('touchstart', function (e) { e.preventDefault(); tryJump(); }, { passive: false });
  const spr = document.getElementById('btn-spr');
  spr.addEventListener('touchstart', function (e) { e.preventDefault(); k.shift = true; }, { passive: false });
  spr.addEventListener('touchend', function () { k.shift = false; });
}

function findClip(clips, key) {
  key = (key || '').toLowerCase();
  let best = null;
  for (let i = 0; i < clips.length; i++) {
    const n = (clips[i].name || '').toLowerCase();
    if (n === key) return clips[i];
    if (n.indexOf(key) !== -1) best = best || clips[i];
  }
  return best;
}

function setupAnims(obj) {
  const k = window.__huggy;
  if (k._animsReady) return;
  const clips = (obj.userData.studio && obj.userData.studio._gltfClips) || [];
  if (!clips.length) return;
  log('Clips: ' + clips.map(function (c) { return c.name; }).join(' | '));

  const mixer = obj.userData._animMixer || new THREE.AnimationMixer(obj);
  obj.userData._animMixer = mixer;
  k.mixer = mixer;

  function make(clip, loop) {
    if (!clip) return null;
    const a = mixer.clipAction(clip);
    a.enabled = true;
    a.setEffectiveWeight(1);
    a.setEffectiveTimeScale(1);
    a.setLoop(loop ? THREE.LoopRepeat : THREE.LoopOnce, loop ? Infinity : 1);
    a.clampWhenFinished = false;
    log('Bound ' + clip.name);
    return a;
  }

  k.actions.walk = make(findClip(clips, 'walk') || findClip(clips, 'skeletonlwalk'), true);
  k.actions.crawl = make(findClip(clips, 'crawl') || findClip(clips, 'skeletonlcrawl'), true);
  k.actions.attack1 = make(findClip(clips, 'attack1') || findClip(clips, 'skeletonlattack1'), false);
  k.actions.attack2 = make(findClip(clips, 'attack2') || findClip(clips, 'skeletonlattack2'), false);
  k.actions.jump = make(findClip(clips, 'jump_start') || findClip(clips, 'skeletonljump_start') || findClip(clips, 'jump'), false);
  k.actions.idle = make(findClip(clips, 'idle'), true);

  mixer.addEventListener('finished', function (ev) {
    const k2 = window.__huggy;
    if (!k2) return;
    if (ev.action === k2.actions.attack1 || ev.action === k2.actions.attack2 || ev.action === k2.actions.jump) {
      k2.lockUntil = 0;
      k2.lockName = '';
      ev.action.fadeOut(0.1);
    }
  });

  if (k.actions.idle) k.actions.idle.play();
  k._animsReady = true;
}

function playOneShot(action, name) {
  const k = window.__huggy;
  if (!action || !k.mixer) return false;
  Object.keys(k.actions).forEach(function (key) {
    const a = k.actions[key];
    if (a && a !== action) a.fadeOut(0.08);
  });
  action.enabled = true;
  action.setEffectiveWeight(1);
  action.setEffectiveTimeScale(1);
  action.reset();
  action.setLoop(THREE.LoopOnce, 1);
  action.clampWhenFinished = false;
  action.fadeIn(0.05);
  action.play();
  const clip = action.getClip();
  const dur = clip && clip.duration ? clip.duration : 0.7;
  k.lockUntil = performance.now() + dur * 1000 + 80;
  k.lockName = name;
  return true;
}

function playLoop(name) {
  const k = window.__huggy;
  if (isLocked()) return;
  let next = k.actions[name];
  if (!next && name === 'crawl') next = k.actions.walk;
  if (!next && name === 'idle') next = k.actions.walk;
  if (!next) return;
  if (k._loopName === name && next.isRunning()) return;
  Object.keys(k.actions).forEach(function (key) {
    const a = k.actions[key];
    if (a && a !== next && a.isRunning()) a.fadeOut(0.12);
  });
  next.enabled = true;
  next.setEffectiveWeight(1);
  next.setEffectiveTimeScale(1);
  next.setLoop(THREE.LoopRepeat, Infinity);
  next.reset().fadeIn(0.12).play();
  k._loopName = name;
  k.lockName = '';
}

function tryAttack() {
  const k = window.__huggy;
  if (!k.started || !object || !k.mixer || isLocked()) return;
  k.attackIndex = k.attackIndex === 1 ? 2 : 1;
  const action = k.actions[k.attackIndex === 1 ? 'attack1' : 'attack2'] || k.actions.attack1;
  if (!playOneShot(action, 'attack')) { log('No attack clip'); return; }
  (window.__runners || []).forEach(function (r) {
    if (!r.alive || !r.object) return;
    if (object.position.distanceTo(r.object.position) <= k.attackRange) r.takeDamage(k.attackDamage);
  });
  log('Attack ' + k.attackIndex);
}

function tryJump() {
  const k = window.__huggy;
  if (!k.started || !k.onGround || isLocked()) return;
  k.vy = k.jumpForce;
  k.onGround = false;
  if (k.actions.jump) playOneShot(k.actions.jump, 'jump');
}

function update(delta) {
  if (!object || !window.__huggy) return;
  const k = window.__huggy;
  delta = Math.min(delta || 0.016, 0.05);
  window.__huggyObject = object;
  if (!k.started) return;

  setupAnims(object);

  if (k.lockUntil && performance.now() >= k.lockUntil) {
    k.lockUntil = 0;
    k.lockName = '';
  }

  let tx = 0, tz = 0;
  if (k.w) tz -= 1;
  if (k.s) tz += 1;
  if (k.a) tx -= 1;
  if (k.d) tx += 1;
  if (k.stickActive) { tx += k.stickX; tz += k.stickY; }
  const tlen = Math.sqrt(tx * tx + tz * tz);
  if (tlen > 1) { tx /= tlen; tz /= tlen; }
  k.inputX += (tx - k.inputX) * Math.min(1, 14 * delta);
  k.inputZ += (tz - k.inputZ) * Math.min(1, 14 * delta);

  const ix = k.inputX, iz = k.inputZ;
  const moving = (ix * ix + iz * iz) > 0.02;
  const fx = -Math.sin(k.yaw), fz = -Math.cos(k.yaw);
  const rx = Math.cos(k.yaw), rz = -Math.sin(k.yaw);
  const mx = rx * ix + fx * (-iz);
  const mz = rz * ix + fz * (-iz);

  const wantsSprint = k.shift && moving && k.stamina > 1;
  if (wantsSprint) k.stamina = Math.max(0, k.stamina - k.staminaDrain * delta);
  else k.stamina = Math.min(k.maxStamina, k.stamina + k.staminaRegen * delta);
  const sprinting = wantsSprint && k.stamina > 1;

  const fill = document.getElementById('stamina-fill');
  if (fill) fill.style.width = (100 * k.stamina / k.maxStamina) + '%';

  k.vy -= k.gravity * delta;
  object.position.y += k.vy * delta;
  if (object.position.y <= k.groundedY) {
    object.position.y = k.groundedY;
    k.vy = 0;
    k.onGround = true;
  }

  const locked = isLocked();
  if (moving && !locked) {
    const spd = sprinting ? k.sprintSpeed : k.walkSpeed;
    object.position.x += mx * spd * delta;
    object.position.z += mz * spd * delta;
    object.rotation.y = Math.atan2(mx, mz);
  }

  if (!locked) {
    if (sprinting) playLoop('crawl');
    else if (moving) playLoop('walk');
    else playLoop('idle');
  }

  if (k.mixer) k.mixer.update(delta);

  const px = object.position.x, py = object.position.y + 1.6, pz = object.position.z;
  const cp = Math.cos(k.pitch), sp = Math.sin(k.pitch);
  camera.position.set(
    px + Math.sin(k.yaw) * cp * k.dist,
    py + sp * k.dist,
    pz + Math.cos(k.yaw) * cp * k.dist
  );
  camera.lookAt(px, py, pz);
}
